#!/bin/bash
# launch of p2-c-px-lt_mb-znn on 3 slot(s) of NODE (default schrodinger): one queue per slot, 1 job each.
# Run on einstein AFTER: preflight ok, a line in phase2_exploration/SLOTS.md, the go of the orchestrator.
# Resume after any stop: run this script again (complete campaigns and done jobs are skipped).
NODE=${1:-schrodinger}
echo "qv2run jobs on $NODE now: $(ssh -x -o BatchMode=yes $NODE "pgrep -u jdochoa -af '[q]v2run job' | wc -l")"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-px-lt-mb; if [ -e /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane0.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane0.pid) 2>/dev/null; then echo lane 0 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane0.pid; exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test/p2-c-px-lt-mb.json' > /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane0.log 2>&1 < /dev/null & echo lane 0 started; fi"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-px-lt-znn-00; if [ -e /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane1.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane1.pid) 2>/dev/null; then echo lane 1 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane1.pid; exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test/p2-c-px-lt-znn-00.json' > /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane1.log 2>&1 < /dev/null & echo lane 1 started; fi"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-px-lt-znn-01; if [ -e /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane2.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane2.pid) 2>/dev/null; then echo lane 2 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane2.pid; exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test/p2-c-px-lt-znn-01.json' > /home/scratch/jdochoa/drivers/p2-c-px-lt_mb-znn_3slots_lane2.log 2>&1 < /dev/null & echo lane 2 started; fi"
